// === Tab: mySketch ===
// By Martin Andersen november 2025 paranoia.holding@proton.me 
// Updated for OpenProcessing p5.js 2.x.x compatibility

let currentImg; // Holds the user-selected or placeholder image
let fileInput;
let thumbNode;  // DOM element for the thumbnail
let paintingDone = false;

function setup() {
  createCanvas(windowWidth, windowHeight, P2D);
  pixelDensity(1); // Enforce density 1 for accurate pixel array math
  background(255);
  noLoop(); 

  // 1. Create a file input element
  fileInput = createFileInput(handleFile);
  fileInput.position(10, 10);
  fileInput.attribute('accept', 'image/*');
  fileInput.style('z-index', '100');

  // 2. Setup the Thumbnail DOM Element (Hidden by default)
  thumbNode = createImg('', 'alt text');
  thumbNode.hide();
  thumbNode.style('position', 'absolute');
  thumbNode.style('bottom', '20px');
  thumbNode.style('right', '20px');
  thumbNode.style('width', '150px');
  thumbNode.style('height', 'auto');
  thumbNode.style('border', '3px solid white');
  thumbNode.style('border-radius', '6px');
  thumbNode.style('box-shadow', '0px 4px 12px rgba(0,0,0,0.5)');
  thumbNode.style('pointer-events', 'none'); // Lets canvas detect clicks
  thumbNode.style('z-index', '1000');

  // 3. Generate and load a beautiful placeholder immediately
  let placeholderGraphics = createPlaceholder();
  let dataUrl = placeholderGraphics.canvas.toDataURL(); // Convert to base64
  loadImage(dataUrl, (img) => {
    imageLoaded(img, dataUrl);
  });
}

/**
 * Procedurally generates a colorful abstract placeholder to start painting instantly
 */
function createPlaceholder() {
  let pg = createGraphics(800, 600);
  pg.background(25, 30, 45);
  pg.noStroke();

  // Draw abstract colorful shapes
  for (let i = 0; i < 200; i++) {
    let r = random(50, 255);
    let g = random(100, 200);
    let b = random(150, 255);
    pg.fill(r, g, b, random(100, 200));

    let x = random(pg.width);
    let y = random(pg.height);
    let size = random(20, 120);

    if (random() > 0.5) pg.circle(x, y, size);
    else {
      pg.push();
      pg.translate(x, y);
      pg.rotate(random(TWO_PI));
      pg.rectMode(CENTER);
      pg.rect(0, 0, size, size * random(0.5, 1.5));
      pg.pop();
    }
  }
  return pg;
}

/**
 * Called when the user uploads a custom file.
 */
function handleFile(file) {
  if (file.type === 'image') {
    loadImage(file.data, (img) => {
      imageLoaded(img, file.data);
    });
  } else {
    console.log("Not an image file!");
  }
}

/**
 * Runs after an image (placeholder or user upload) is fully loaded.
 */
function imageLoaded(loadedImg, originalSrc) {
  currentImg = loadedImg;
  paintingDone = false;

  // Update thumbnail source and ensure it's hidden while painting
  thumbNode.attribute('src', originalSrc);
  thumbNode.hide();

  // Resize the image to fit the canvas proportionally
  currentImg.resize(0, height); 
  if (currentImg.width > width) {
    currentImg.resize(width, 0);
  }

  // Start the painting process
  background(255);
  frameCount = 0; 
  currentImg.loadPixels(); 
  loop(); 
}

// --- NO CHANGES to paintStroke() ---
function paintStroke(strokeLength, strokeColor, strokeThickness) {
  let stepLength = strokeLength / 4.0;
  let tangent1 = 0;
  let tangent2 = 0;
  let odds = random(1.0);

  if (odds < 0.7) {
    tangent1 = random(-strokeLength, strokeLength);
    tangent2 = random(-strokeLength, strokeLength);
  }

  noFill();
  stroke(strokeColor);
  strokeWeight(strokeThickness);
  curve(tangent1, -stepLength * 2, 0, -stepLength, 0, stepLength, tangent2, stepLength * 2);

  let z = 1;
  for (let num = strokeThickness; num > 0; num--) {
    let offset = random(-50, 25);
    let newColor = color(red(strokeColor) + offset, green(strokeColor) + offset, blue(strokeColor) + offset, random(100, 255));
    stroke(newColor);
    strokeWeight(int(random(0, 3)));
    curve(tangent1, -stepLength * 2, z - strokeThickness / 2, -stepLength * random(0.9, 1.1), z - strokeThickness / 2, stepLength * random(0.9, 1.1), tangent2, stepLength * 2);
    z += 1;
  }
}

function draw() {
  if (!currentImg) return; 

  translate(width / 2, height / 2);

  let strokesPerFrame = 50; 
  for (let i = 0; i < strokesPerFrame; i++) {
    var x = int(random(currentImg.width));
    var y = int(random(currentImg.height));

    // Get the pixel color using standard array math 
    let index = (x + y * currentImg.width) * 4;
    var r = currentImg.pixels[index];
    var g = currentImg.pixels[index + 1];
    var b = currentImg.pixels[index + 2];
    let pixelColor = color(r, g, b, 100);

    // Draw the stroke
    push();
    translate(x - currentImg.width / 2, y - currentImg.height / 2);
    rotate(radians(random(-90, 90)));

    if (frameCount < 20) {
      paintStroke(random(150, 250), pixelColor, int(random(20, 40)));
    } else if (frameCount < 50) {
      paintStroke(random(75, 125), pixelColor, int(random(8, 12)));
    } else if (frameCount < 300) {
      paintStroke(random(30, 60), pixelColor, int(random(1, 4)));
    } else if (frameCount < 350) {
      paintStroke(random(5, 20), pixelColor, int(random(5, 15)));
    } else if (frameCount < 600) {
      paintStroke(random(1, 10), pixelColor, int(random(1, 7)));
    }
    pop();
  }

  // Stop painting and enable the thumbnail toggle
  if (frameCount > 600) {
    paintingDone = true;
    noLoop();
  }
}

/**
 * Toggles the original image thumbnail when clicking/touching the canvas 
 * AFTER the painting process is complete.
 */
function mousePressed() {
  if (paintingDone && currentImg) {
    if (thumbNode.style('display') === 'none') {
      thumbNode.style('display', 'block');
    } else {
      thumbNode.style('display', 'none');
    }
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  // Re-draw background. If we wanted to, we could restart the painting here by calling loop()
  background(255);
  if (currentImg) {
    frameCount = 0;
    paintingDone = false;
    thumbNode.hide();
    loop(); // Restart painting sequence on resize
  }
}

